import hashlib
from datetime import date, timedelta

def generate_date_range(start_date, end_date):
    current_date = start_date
    while current_date <= end_date:
        yield current_date
        current_date += timedelta(days=1)

def crack_password(hash_to_match, name, start_date, end_date):
    for current_date in generate_date_range(start_date, end_date):
        date_str = current_date.strftime('%Y%m%d')
        password = f"{name}{date_str}"
        md5_hash = hashlib.md5(password.encode()).hexdigest()
        if md5_hash == hash_to_match:
            return password
    return None

if __name__ == "__main__":
    target_hash = "7f4986da7d7b52fa81f98278e6ec9dcb"
    name = "Aaron"
    start_date = date(1950, 1, 1)
    end_date = date(2023, 1, 1)

    cracked_password = crack_password(target_hash, name, start_date, end_date)
    if cracked_password:
        print(f"Flag: flag{{{cracked_password}}}")
    else:
        print("Password not found in the given range.")
